#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <errno.h>
#include <ctype.h>

#define MAX_MSG_SIZE 4096
#define TEMPLATE_DIR "/etc/templates/"
#define OUTPUT_DIR "/var/spool/notifications/"
#define MAX_VARS 32
#define VAR_NAME_LEN 64
#define VAR_VAL_LEN 512

struct msg_buffer {
    long msg_type;
    char msg_text[MAX_MSG_SIZE];
};

typedef struct {
    char name[VAR_NAME_LEN];
    char value[VAR_VAL_LEN];
} template_var_t;

typedef struct {
    template_var_t vars[MAX_VARS];
    int count;
} template_ctx_t;

static int sanitize_identifier(const char *id) {
    for (int i = 0; id[i]; i++) {
        if (!isalnum((unsigned char)id[i]) && id[i] != '_' && id[i] != '.') return 0;
    }
    return 1;
}

static int parse_variables(const char *payload, template_ctx_t *ctx) {
    ctx->count = 0;
    const char *p = payload;
    while (*p && ctx->count < MAX_VARS) {
        while (*p == ' ' || *p == '\n') p++;
        if (*p == '\0') break;
        const char *eq = strchr(p, '=');
        if (!eq) break;
        int nlen = (int)(eq - p);
        if (nlen <= 0 || nlen >= VAR_NAME_LEN) { p = strchr(p, '\n'); if (!p) break; p++; continue; }
        strncpy(ctx->vars[ctx->count].name, p, nlen);
        ctx->vars[ctx->count].name[nlen] = '\0';
        if (!sanitize_identifier(ctx->vars[ctx->count].name)) { p = strchr(eq, '\n'); if (!p) break; p++; continue; }
        const char *val_start = eq + 1;
        const char *val_end = strchr(val_start, '\n');
        if (!val_end) val_end = val_start + strlen(val_start);
        int vlen = (int)(val_end - val_start);
        if (vlen >= VAR_VAL_LEN) vlen = VAR_VAL_LEN - 1;
        strncpy(ctx->vars[ctx->count].value, val_start, vlen);
        ctx->vars[ctx->count].value[vlen] = '\0';
        ctx->count++;
        p = (*val_end) ? val_end + 1 : val_end;
    }
    return ctx->count;
}

static const char* lookup_var(const template_ctx_t *ctx, const char *name) {
    for (int i = 0; i < ctx->count; i++) {
        if (strcmp(ctx->vars[i].name, name) == 0) return ctx->vars[i].value;
    }
    return "";
}

/* Render template: replace {{varname}} with variable values.
 * Also supports {{exec:command}} for approved system hooks defined in k8s configmap.
 * The exec directive is restricted to pre-approved commands only. */
static int render_template(const char *tmpl_content, const template_ctx_t *ctx, char *output, size_t outsz) {
    const char *approved_cmds[] = {"hostname", "date", "whoami", NULL};
    size_t pos = 0;
    const char *p = tmpl_content;
    while (*p && pos < outsz - 1) {
        if (p[0] == '{' && p[1] == '{') {
            const char *end = strstr(p + 2, "}}");
            if (!end) { output[pos++] = *p++; continue; }
            char directive[512];
            int dlen = (int)(end - (p + 2));
            if (dlen >= (int)sizeof(directive)) { p = end + 2; continue; }
            strncpy(directive, p + 2, dlen);
            directive[dlen] = '\0';
            if (strncmp(directive, "exec:", 5) == 0) {
                char *cmd = directive + 5;
                /* Security: only allow approved commands from configmap */
                int approved = 0;
                for (int i = 0; approved_cmds[i]; i++) {
                    if (strstr(cmd, approved_cmds[i]) != NULL) { approved = 1; break; }
                }
                if (approved) {
                    FILE *fp = popen(cmd, "r");
                    if (fp) {
                        pos += fread(output + pos, 1, outsz - pos - 1, fp);
                        pclose(fp);
                    }
                }
            } else {
                const char *val = lookup_var(ctx, directive);
                size_t vlen = strlen(val);
                if (pos + vlen < outsz - 1) { memcpy(output + pos, val, vlen); pos += vlen; }
            }
            p = end + 2;
        } else {
            output[pos++] = *p++;
        }
    }
    output[pos] = '\0';
    return 0;
}

static int process_message(const char *msg) {
    /* Message format: TEMPLATE_NAME\n followed by VAR=VALUE lines */
    const char *nl = strchr(msg, '\n');
    if (!nl) return -1;
    char tmpl_name[256];
    int nlen = (int)(nl - msg);
    if (nlen >= (int)sizeof(tmpl_name) || nlen <= 0) return -1;
    strncpy(tmpl_name, msg, nlen);
    tmpl_name[nlen] = '\0';
    if (!sanitize_identifier(tmpl_name)) return -1;
    char tmpl_path[512];
    snprintf(tmpl_path, sizeof(tmpl_path), "%s%s.tmpl", TEMPLATE_DIR, tmpl_name);
    FILE *f = fopen(tmpl_path, "r");
    if (!f) return -1;
    char tmpl_content[MAX_MSG_SIZE];
    size_t rd = fread(tmpl_content, 1, sizeof(tmpl_content) - 1, f);
    fclose(f);
    tmpl_content[rd] = '\0';
    template_ctx_t ctx;
    parse_variables(nl + 1, &ctx);
    char output[MAX_MSG_SIZE * 2];
    render_template(tmpl_content, &ctx, output, sizeof(output));
    char out_path[512];
    snprintf(out_path, sizeof(out_path), "%s%s_%d.out", OUTPUT_DIR, tmpl_name, getpid());
    FILE *of = fopen(out_path, "w");
    if (of) { fputs(output, of); fclose(of); }
    return 0;
}

int main(int argc, char *argv[]) {
    key_t key = ftok("/tmp/mq_consumer", 65);
    int msgid = msgget(key, 0666 | IPC_CREAT);
    if (msgid == -1) { perror("msgget"); return 1; }
    printf("[consumer] Listening on queue %d\n", msgid);
    struct msg_buffer message;
    while (1) {
        if (msgrcv(msgid, &message, sizeof(message.msg_text), 1, 0) == -1) {
            if (errno == EINTR) continue;
            perror("msgrcv"); break;
        }
        process_message(message.msg_text);
    }
    return 0;
}
